;\n  padding-top: 2rem;\n  padding-bottom: 0.5rem; }\n\n.page-title .sub-title {\n  font-size: 1.2rem; }\n\n.page-results {\n  margin: 1.5rem 1.5rem 0; }\n\n.page-form {\n  margin: 1.5rem 1.5rem 0;\n  padding-top: 1rem;\n  padding-bottom: 1rem;\n  background: #fff;\n  box-shadow: 0 2px 2px 0 rgba(0, 0, 0, 0.14), 0 3px 1px -2px rgba(0, 0, 0, 0.2), 0 1px 5px 0 rgba(0, 0, 0, 0.12); }\n  .page-form .row {\n    margin-bottom: 0; }\n    .page-form .row .col {\n      padding: 0 1.5rem; }\n  .page-form .input-field {\n    font-size: 1.2rem; }\n    .page-form .input-field label {\n      left: 1.5rem;\n      font-size: 1.1rem;\n      color: #808080; }\n    .page-form .input-field input[type=text] {\n      height: 3.5rem;\n      line-height: 3.5rem;\n      border-color: #ccc;\n      font-size: 1.2rem;\n      color: #2c2c2c;\n      margin-bottom: 10px; }\n      .page-form .input-field input[type=text][readonly=\"readonly\"] {\n        border-bottom: 1px solid #ccc; }\n        .page-form .input-field input[type=text][readonly=\"readonly\"] + label {\n          color: #808080; }\n      .page-form .input-field input[type=text]:focus:not([readonly]) {\n        border-color: #549cba; }\n        .page-form .input-field input[type=text]:focus:not([readonly]) + label {\n          color: #549cba; }\n    .page-form .input-field ::-webkit-input-placeholder {\n      /* Chrome/Opera/Safari */\n      color: #2c2c2c; }\n    .page-form .input-field .icon-calendar {\n      position: absolute;\n      right: 15px;\n      top: 10px;\n      font-size: 16px;\n      color: #4d6273; }\n  .page-form .dropdown-content {\n    margin-top: 5px;\n    max-height: 400px; }\n  .page-form .dropdown-content li > a, .page-form .dropdown-content li > span {\n    font-size: 1.2rem;\n    color: #2c2c2c; }\n  .page-form .select-wrapper {\n    /*span.caret {\r\n            color: $blue-light;\r\n        }*/ }\n    .page-form .select-wrapper input.select-dropdown {\n      height: 3.5rem;\n      line-height: 3.5rem;\n      border-color: #ccc;\n      font-size: 1.2rem;\n      color: #2c2c2c;\n      margin-bottom: 10px; }\n    .page-form .select-wrapper span.caret {\n      font-family: 'icomoon' !important;\n      color: transparent; }\n      .page-form .select-wrapper span.caret:before {\n        content: \"\\e916\";\n        color: #4d6273;\n        font-size: 18px;\n        position: absolute;\n        top: -7px;\n        right: -5px; }\n\n.table-title {\n  background: #8aa4b8;\n  padding: 4px 15px;\n  color: #fff;\n  text-transform: uppercase; }\n\n.panel-heading {\n  background: #4C6375;\n  border-radius: 0;\n  padding: 0; }\n  .panel-heading .panel-title {\n    color: #fff;\n    padding: 5px 15px;\n    font-size: 13px; }\n    .panel-heading .panel-title .icon-arrow {\n      margin: 0;\n      font-size: 13px;\n      transform: rotate(-90deg);\n      transition: 0.3s ease all; }\n    .panel-heading .panel-title:hover, .panel-heading .panel-title:active, .panel-heading .panel-title:focus {\n      color: #fff; }\n  .panel-heading + .panel-collapse > .panel-body {\n    border-top: none !important; }\n  .panel-heading.active .panel-title .icon-arrow {\n    transform: rotate(0); }\n\n.table {\n  table-layout: fixed; }\n\n.no-info-row {\n  text-align: center;\n  border: 1px solid #ccc;\n  padding: 5px; }\n\n\n\n/** WEBPACK FOOTER **\n ** webpack:///www/css/source/pages/common.scss\n **/",".system-parlay-detail-container .system-parlay-header th {\n  background-color: #C7E9F5;\n  border-left: 1px solid #FFFFFF;\n  color: #024584;\n  background-image: url(\"images/tab_topbg.gif\");\n  background-position: center bottom;\n  background-repeat: repeat-x;\n  font-size: 11px;\n  font-weight: normal;\n  height: 28px;\n  padding: 2px;\n  text-align: center;\n  vertical-align: middle; }\n\n.system-parlay-detail-container .system-parlay-detail td {\n  border-top: 1px solid #A3D1E1 !important;\n  border-bottom: 1px solid #A3D1E1;\n  border-left: 1px solid #A3D1E1;\n  color: #454545;\n  font-size: 11px;\n  height: 22px;\n  padding: 2px;\n  text-align: right;\n  vertical-align: middle; }\n\n.system-parlay-detail-container .system-parlay-outstanding {\n  background-color: #F8F1A0;\n  color: #003333;\n  font-weight: bold !important;\n  margin: 5px 0;\n  text-align: right; }\n\n.system-parlay-detail-container .system-parlay-subtotal {\n  background-color: #FFA07A; }\n\n.system-parlay-detail-container .system-parlay-total {\n  background-color: #B2DFEF; }\n\n\n\n/** WEBPACK FOOTER **\n ** webpack:///www/css/source/components/betlist/systemparlaydetail.scss\n **/"],"sourceRoot":""}
